update public.catalog_servicii set traduceri = jsonb_set(coalesce(traduceri, '{}'::jsonb), '{en}', '{"titlu":"Laminate Flooring Installation","domeniu":"Flooring & Parquet","descriere":"Professional laminate flooring installation, carried out by a qualified tradesperson (category II floor fitter), according to the technical standard of 0.35 hours/m². The flooring (classes AC3–AC5), the underlay and the accessories (skirting, transition profile) are chosen separately, as optional materials, from the selector below or from the dedicated marketplace.","etape_lucrare":["Checking and preparing the screed (flatness, moisture, cleanliness)","Laying the underlay over the whole area","Laying the laminate flooring, with expansion gaps at the walls","Fitting the accessories (skirting, transition profile), if ordered","Final cleaning and handover of the work"],"instructiuni_intretinere":"Clean with a brush/vacuum cleaner or a slightly damp mop, without excess water. Avoid abrasive products and wax. Use felt pads under furniture to prevent scratches. Avoid prolonged exposure to direct sunlight and sudden changes in humidity, to prevent warping.","unitate_masura":"m²"}'::jsonb || coalesce(traduceri->'en', '{}'::jsonb)) where id = '59c4f00a-5438-4a70-9b6b-0fc142f243bc' and status_public and titlu = 'Montaj Parchet Laminat' and domeniu = 'Pardoseli & Parchet' and descriere = 'Montaj profesional de parchet laminat, executat de meseriaș calificat (Parchetar categoria II), conform normei tehnice de 0,35 ore/mp. Parchetul (clasele AC3–AC5), folia izolatoare și accesoriile (plintă, profil de trecere) se aleg separat, ca materiale opționale, din selectorul de mai jos sau din marketplace-ul dedicat.' and to_jsonb(etape_lucrare) = '["Verificarea și pregătirea șapei (planeitate, umiditate, curățenie)","Montarea foliei izolatoare pe toată suprafața","Montarea parchetului laminat, cu rosturi de dilatare la pereți","Montarea accesoriilor (plintă, profil de trecere), dacă au fost comandate","Curățenie finală și predarea lucrării"]'::jsonb and instructiuni_intretinere = 'Curățare cu mătură/aspirator sau mop ușor umezit, fără exces de apă. Evitați substanțele abrazive și ceara. Folosiți protecții din pâslă sub mobilier, pentru a preveni zgârieturile. Evitați expunerea prelungită la soare direct și variațiile bruște de umiditate, pentru a preveni deformarea.' and unitate_masura = 'mp';
